expressions.expression_template:
loopDuration = {duration};
startVal = {start_value};
endVal = {end_value};
pingPong = linear(time % (loopDuration * 2), 0, loopDuration * 2, startVal, endVal);
linear(pingPong, startVal, endVal, startVal, endVal)

freq = {frequency};
amp = {amplitude};
Math.sin(time * freq) * amp

startScale = {start_scale};
endScale = {end_scale};
duration = {duration};
linear(time, 0, duration, startScale, endScale) * (1 + Math.pow(time/{acceleration}, 2))

delay = {delay_per_item};
myIndex = {index_offset};
startTime = {start_time};
if (time >= startTime + (myIndex * delay)) {
  // Основний вираз
  {main_expression};
} else {
  value;
}

seedRandom({seed}, timeless = true);
minOpacity = {min_opacity};
maxOpacity = {max_opacity};
if (random() > {flicker_chance}) {
  random(minOpacity, maxOpacity);
} else {
  value;
}

centerX = {center_x};
centerY = {center_y};
radius = {radius};
speed = {speed};
angle = time * speed;
[centerX + Math.sin(angle) * radius, centerY + Math.cos(angle) * radius]

centerX = {center_x};
centerY = {center_y};
startRadius = {start_radius};
endRadius = {end_radius};
rotations = {rotations};
duration = {duration};

progress = linear(time, 0, duration, 0, 1);
currentRadius = linear(progress, 0, 1, startRadius, endRadius);
angle = progress * rotations * 2 * Math.PI;

[centerX + Math.sin(angle) * currentRadius, centerY + Math.cos(angle) * currentRadius]

target = {target_value};
current = value;
velocity = {initial_velocity};
spring = {spring_strength};
damping = {damping};

for (i = 0; i < time * {precision}; i++) {
  force = (target - current) * spring;
  velocity += force;
  velocity *= damping;
  current += velocity;
}
current

gravity = {gravity};
bounce = {bounce_factor};
friction = {friction};
startHeight = {start_height};

velocity = 0;
height = startHeight;

for (i = 0; i < time * {precision}; i++) {
  velocity -= gravity;
  height += velocity;

  if (height <= 0) {
    height = 0;
    velocity = -velocity * bounce;
    velocity *= friction;
  }
}
height

audioLayer = thisComp.layer("{audio_layer_name}");
smoothFrames = {smooth_frames};

if (audioLayer != null) {
  amplitude = 0;
  for (i = 0; i <= smoothFrames; i++) {
    amplitude += audioLayer.sampleImage([0.5, 0.5], [time - i * thisComp.frameDuration, 0.5])[0];
  }
  amplitude / (smoothFrames + 1) * {multiplier};
} else {
  0;
}

function detectBeat() {
  audioLayer = thisComp.layer("{audio_layer_name}");
  threshold = {sensitivity};
  lookback = {lookback_frames};

  if (audioLayer == null) return 0;

  currentAmp = audioLayer.sampleImage([0.5, 0.5], [time, 0.5])[0] * 100;
  pastAmp = audioLayer.sampleImage([0.5, 0.5], [time - lookback * thisComp.frameDuration, 0.5])[0] * 100;

  if (currentAmp > pastAmp + threshold && currentAmp > {minimum_amplitude}) {
    100; // Beat detected!
  } else {
    0;
  }
}

detectBeat()

audioLayer = thisComp.layer("{audio_layer_name}");
frequencyBand = "{frequency_band}";

if (audioLayer != null) {
  // Спрощена емуляція частотних фільтрів
  baseAmp = audioLayer.sampleImage([0.5, 0.5], [time, 0.5])[0] * 100;

  if (frequencyBand == "bass") {
    baseAmp * {bass_boost};
  } else if (frequencyBand == "treble") {
    baseAmp * {treble_boost};
  } else {
    baseAmp; // mids
  }
} else {
  0;
}

fullText = "{text_content}";
charsPerSecond = {typing_speed};
startTime = {start_time};
showCursor = {show_cursor};

charsToShow = Math.floor((time - startTime) * charsPerSecond);
result = fullText.substring(0, charsToShow);

if (showCursor && charsToShow < fullText.length) {
  result + "{cursor_character}";
} else {
  result;
}

seedRandom({seed}, timeless = true);
baseText = "{text_content}";
maxOffset = {jitter_strength};

result = "";
for (i = 0; i < baseText.length; i++) {
  charOffset = random(-maxOffset, maxOffset);
  // Емулюємо тремтіння через зміну позиції символу
  result += baseText[i];
}
result

text = "{text_content}";
waveHeight = {wave_height};
waveSpeed = {wave_speed};

sourceText = text;
if (sourceText.numKeys > 0) sourceText = sourceText.value;

result = "";
for (i = 0; i < sourceText.length; i++) {
  charOffset = Math.sin(time * waveSpeed + i * {phase_shift}) * waveHeight;
  // У реальному експрешені це буде впливати на позицію символу
  result += sourceText[i];
}
result

target = thisComp.layer("{target_layer}").transform.position;
radius = {orbit_radius};
height = {orbit_height};
speed = {orbit_speed};

angle = time * speed;
x = target[0] + Math.cos(angle) * radius;
z = target[2] + Math.sin(angle) * radius;
y = target[1] + height;

[x, y, z]

target = thisComp.layer("{target_layer}").transform.position;
myPos = transform.position;

// Розрахунок напрямку
dir = target - myPos;

// Для 2D обертання
angle = Math.atan2(dir[1], dir[0]);
radiansToDegrees(angle)

intensity = {shake_intensity};
frequency = {shake_frequency};

// Тремтіння позиції
posX = wiggle(frequency, intensity)[0];
posY = wiggle(frequency, intensity)[1]; 
posZ = wiggle(frequency, intensity * 0.5)[0]; // Менше тремтіння по Z

// Тремтіння обертання
rotX = wiggle(frequency, intensity * 0.3)[0];
rotY = wiggle(frequency, intensity * 0.3)[1];
rotZ = wiggle(frequency, intensity * 0.2)[0];

// Комбінуємо з оригінальними значеннями
originalPos = value;
originalRot = transform.rotation.value;

[originalPos[0] + posX, originalPos[1] + posY, originalPos[2] + posZ]

focusLayer = thisComp.layer("{focus_target}");
myPos = transform.position;
targetPos = focusLayer.transform.position;

// Розрахунок відстані
distance = length(myPos, targetPos);

// Додаємо зсув для творчого контролю
distance + {focus_offset}

scrollSpeed = {scroll_speed};
depthFactor = {depth_factor};

// Рух залежно від глибини
xMove = time * scrollSpeed * depthFactor;
originalPos = value;

[originalPos[0] + xMove, originalPos[1]]

// Отримуємо позицію миші (потребує плагіна)
mouseX = thisComp.layer("Controller").effect("Mouse X")("Slider");
mouseY = thisComp.layer("Controller").effect("Mouse Y")("Slider");

// Плавне відстеження
smoothFactor = {smoothness};
currentX = value[0];
currentY = value[1];

newX = currentX + (mouseX - currentX) * smoothFactor;
newY = currentY + (mouseY - currentY) * smoothFactor;

[newX, newY]

duration = {load_duration};
startTime = {start_time};
style = "{progress_style}";

progress = linear(time - startTime, 0, duration, 0, 100);

if (style == "smooth") {
  ease(progress, 0, 100, 0, 100);
} else if (style == "bounce") {
  // Додаємо невелике відскакування в кінці
  progress + Math.sin(progress * 10) * 2;
} else {
  progress; // linear
}

masterControl = thisComp.layer("Controller").effect("Master Control")("Slider");

// Використовуємо masterControl для керування різними параметрами
if (masterControl > {activation_threshold}) {
  // Активуємо анімацію
  {active_expression};
} else {
  // Стан спокою
  {idle_expression};
}

inputValue = {input_value};
minVal = {minimum};
maxVal = {maximum};
smoothness = {edge_smoothness};

// Плавне обмеження
if (inputValue < minVal) {
  ease(inputValue, minVal - smoothness, minVal, minVal - smoothness, minVal);
} else if (inputValue > maxVal) {
  ease(inputValue, maxVal, maxVal + smoothness, maxVal, maxVal + smoothness);
} else {
  inputValue;
}

inputValue = {input_value};
inputMin = {input_min};
inputMax = {input_max};
outputMin = {output_min};
outputMax = {output_max};

linear(inputValue, inputMin, inputMax, outputMin, outputMax)

condition = {input_value} {condition_operator} {threshold_value};

if (condition) {
  // Якщо умова виконується
  {true_expression};
} else {
  // Якщо умова не виконується
  {false_expression};
}

targetValue = {target_value};
smoothFactor = {smoothing};

// Експоненційне згладжування
currentValue = value;
currentValue + (targetValue - currentValue) * smoothFactor

seedRandom({seed}, timeless = true);
colorSpeed = {color_speed};

hue = (time * colorSpeed * 360 + random(0, 360)) % 360;
saturation = random({min_saturation}, {max_saturation});
lightness = random({min_lightness}, {max_lightness});

// Конвертація HSL to RGB (спрощено)
[ hue/360, saturation/100, lightness/100, {alpha} ]

pulseRate = {pulse_rate};
pulseStrength = {pulse_strength};
baseValue = {base_value};

pulse = Math.sin(time * pulseRate * 2 * Math.PI) * pulseStrength;
baseValue + pulse

waveFrequency = {wave_frequency};
waveAmplitude = {wave_amplitude};
waveSpeed = {wave_speed};

x = value[0] + Math.sin(time * waveSpeed + value[1] * waveFrequency) * waveAmplitude;
y = value[1] + Math.cos(time * waveSpeed + value[0] * waveFrequency) * waveAmplitude;

[x, y]

targets = [
  {target_1},
  {target_2}, 
  {target_3},
  {target_4}
];
switchTime = {switch_interval};

currentTargetIndex = Math.floor(time / switchTime) % targets.length;
nextTargetIndex = (currentTargetIndex + 1) % targets.length;

blend = (time % switchTime) / switchTime;

// Плавний перехід між цілями
linear(blend, 0, 1, targets[currentTargetIndex], targets[nextTargetIndex])

currentHealth = {current_health};
maxHealth = {max_health};
damageEffect = {damage_effect};

healthPercent = (currentHealth / maxHealth) * 100;

// Ефект пошкодження (червоний спалах)
if (damageEffect > 0) {
  healthPercent + Math.sin(time * 30) * damageEffect;
} else {
  healthPercent;
}

isHovered = {is_hovered};
isPressed = {is_pressed};
isActive = {is_active};

baseScale = 100;

// Анімація наведення
if (isHovered) {
  baseScale += {hover_scale};
}

// Анімація натискання
if (isPressed) {
  baseScale -= {press_scale};
}

// Стан активності
if (isActive) {
  baseScale += {active_scale};
}

baseScale

targetScore = {target_score};
currentScore = {current_score};
animationSpeed = {animation_speed};

// Плавне наближення до цільового значення
if (currentScore < targetScore) {
  currentScore + (targetScore - currentScore) * animationSpeed;
} else if (currentScore > targetScore) {
  currentScore - (currentScore - targetScore) * animationSpeed;
} else {
  currentScore;
}

seedRandom({seed}, timeless = false);
baseGlow = {base_glow};
pulseAmount = {pulse_amount};
flickerChance = {flicker_chance};

// Базова пульсація
pulse = Math.sin(time * {pulse_speed}) * pulseAmount;

// Випадкові спалахи
flicker = random() < flickerChance ? {flicker_intensity} : 0;

baseGlow + pulse + flicker

streamSpeed = {stream_speed};
characterSet = "{characters}";
density = {stream_density};

seedRandom({seed}, timeless = false);

// Генерація випадкових символів, що рухаються
result = "";
for (i = 0; i < density; i++) {
  charIndex = Math.floor(random() * characterSet.length);
  result += characterSet[charIndex];
}
result

flickerIntensity = {flicker_intensity};
noiseAmount = {noise_amount};
distortion = {distortion_strength};

seedRandom({seed}, timeless = false);

// Мерехтіння прозорості
flicker = random() > 0.7 ? random(0.3, 1) : 1;

// Шум позиції
noiseX = random(-noiseAmount, noiseAmount);
noiseY = random(-noiseAmount, noiseAmount);

// Спотворення масштабу
scaleDistortion = 1 + random(-distortion, distortion);

// Комбінуємо всі ефекти
value * flicker * scaleDistortion + [noiseX, noiseY]

rewindSpeed = {rewind_speed};
startTime = {start_time};
rewindDuration = {rewind_duration};

// Розрахунок часу для перемотування
if (time >= startTime && time < startTime + rewindDuration) {
  rewindTime = startTime + (startTime + rewindDuration - time) * rewindSpeed;
  valueAtTime(rewindTime);
} else {
  value;
}

seedRandom({seed}, timeless = false);
particleSpeed = {particle_speed};
spread = {spread_amount};
gravity = {gravity_strength};
lifeTime = {particle_lifetime};

// Випадкова початкова швидкість
initialX = random(-spread, spread);
initialY = random(-spread, spread);

// Рух з гравітацією
currentX = initialX * particleSpeed * time;
currentY = initialY * particleSpeed * time + 0.5 * gravity * time * time;

// Обмеження часу життя
if (time > lifeTime) {
  [0, 0]; // Повертаємо в початок
} else {
  [currentX, currentY];
}

magnetPos = thisComp.layer("{magnet_layer}").transform.position;
myPos = transform.position;
fieldStrength = {field_strength};
polarity = {magnet_polarity};

// Вектор до магніту
dir = magnetPos - myPos;
distance = length(dir);

// Сила поля (обернено пропорційна квадрату відстані)
force = (fieldStrength * polarity) / (distance * distance + 1);

// Застосовуємо силу
myPos + normalize(dir) * force

waveHeight = {wave_height};
waveFrequency = {wave_frequency};
viscosity = {viscosity};
surfaceTension = {surface_tension};

// Основний хвильовий рух
baseWave = Math.sin(time * waveFrequency + value[0] * 0.01) * waveHeight;

// Ефект в'язкості (заспокоєння)
damping = Math.exp(-time * viscosity);

// Поверхневий натяг (швидкі коливання)
tension = Math.sin(time * surfaceTension * 10) * 2;

value + [0, baseWave * damping + tension]

audioLayer = thisComp.layer("{audio_layer}");
bandIndex = {frequency_band};
numBands = {total_bands};
sensitivity = {band_sensitivity};

if (audioLayer != null) {
  // Спрощена емуляція частотних смуг
  baseAmp = audioLayer.sampleImage([0.5, 0.5], [time, 0.5])[0] * 100;

  // Різні смуги реагують по-різному
  bandMultiplier = 1 + (bandIndex / numBands) * sensitivity;

  baseAmp * bandMultiplier;
} else {
  0;
}

audioLayer = thisComp.layer("{audio_layer}");
beatThreshold = {beat_threshold};
reactionStrength = {reaction_strength};
reactionDuration = {reaction_duration};

if (audioLayer != null) {
  currentAmp = audioLayer.sampleImage([0.5, 0.5], [time, 0.5])[0] * 100;
  previousAmp = audioLayer.sampleImage([0.5, 0.5], [time - thisComp.frameDuration, 0.5])[0] * 100;

  // Детекція битів
  if (currentAmp > previousAmp + beatThreshold) {
    // Сильна реакція на бит
    value + reactionStrength;
  } else {
    // Плавне повернення
    value + (reactionStrength * Math.exp(-time / reactionDuration));
  }
} else {
  value;
}

revealType = "{reveal_type}";
revealSpeed = {reveal_speed};
startTime = {start_time};

progress = (time - startTime) * revealSpeed;

if (revealType == "left_to_right") {
  // Зліва направо
  [progress * {comp_width}, 0];
} else if (revealType == "top_to_bottom") {
  // Зверху вниз
  [0, progress * {comp_height}];
} else if (revealType == "center") {
  // З центру
  radius = progress * Math.max({comp_width}, {comp_height});
  [radius, radius];
} else {
  // Діагональ
  [progress * {comp_width}, progress * {comp_height}];
}

charIndex = {character_index};
staggerDelay = {stagger_delay};
animationType = "{animation_type}";

// Затримка для кожного символу
charTime = time - (charIndex * staggerDelay);

if (charTime >= 0) {
  if (animationType == "bounce") {
    // Стрибок
    Math.sin(charTime * {bounce_speed}) * {bounce_height};
  } else if (animationType == "fade") {
    // Поступове з'явлення
    linear(charTime, 0, {fade_duration}, 0, 100);
  } else if (animationType == "scale") {
    // Масштабування
    ease(charTime, 0, {scale_duration}, 0, 100);
  } else {
    // Простий рух
    charTime * {move_speed};
  }
} else {
  0;
}

controller = thisComp.layer("{controller_layer}");
parameter = "{controlled_parameter}";

if (controller != null) {
  // Отримуємо значення з контролера
  masterValue = controller.effect("Master Control")("Slider");

  // Застосовуємо до різних параметрів
  if (parameter == "scale") {
    masterValue;
  } else if (parameter == "position") {
    [masterValue, masterValue];
  } else if (parameter == "rotation") {
    masterValue * 3.6; // Для градусів
  } else if (parameter == "opacity") {
    masterValue;
  }
} else {
  value;
}

currentMode = {current_mode};

if (currentMode == "mode_1") {
  // Перший режим - плавна анімація
  {expression_1};
} else if (currentMode == "mode_2") {
  // Другий режим - різка анімація
  {expression_2};
} else if (currentMode == "mode_3") {
  // Третій режим - випадкова анімація
  {expression_3};
} else {
  // Режим за замовчуванням
  value;
}

originalExpression = {original_expression};
updateRate = {update_frequency};

// Оновлюємо значення тільки кожні N кадрів
if (Math.floor(time / thisComp.frameDuration) % updateRate == 0) {
  eval(originalExpression);
} else {
  value;
}
